select case when a.balance >= 61000 then 'high' when a.balance >= 20000 then 'mid' else 'low' end as balance_bucket, a.status, avg(t.amount) as avg_amount from transactions t inner join accounts a on t.account_id = a.id inner join customers c on c.id = a.customer_id where t.txn_type = 'DEBIT' group by case when a.balance >= 61000 then 'high' when a.balance >= 20000 then 'mid' else 'low' end, a.status;
